    <!-- Item 2 -->
    <div class="item">
      <div class="photo-placeholder"></div>
      <div class="item-info">
        <div class="item-name">حليب</div>
        <div class="stepper">
          <button class="decrease">-</button>
          <input type="number" value="2" min="0">
          <button class="increase">+</button>
        </div>
      </div>
      <div class="item-price">5.00 د.إ</div>
    </div>

    <!-- Item 3 -->
    <div class="item">
      <div class="photo-placeholder"></div>
      <div class="item-info">
        <div class="item-name">بروتين</div>
        <div class="stepper">
          <button class="decrease">-</button>
          <input type="number" value="1" min="0">
          <button class="increase">+</button>
        </div>
      </div>
      <div class="item-price">20.00 د.إ</div>
    </div>

    <!-- Promo code -->
    <div class="promo">
      <input type="text" placeholder="رمز الخصم">
    </div>

    <!-- Summary -->
