      <div class="row subtotal">
        <span>الإجمالي الفرعي</span>
        <span>0.00 د.إ</span>
      </div>
      <div class="row delivery">
        <span>الdelivery</span>
        <span>10.00 د.إ</span>
      </div>
      <div class="row vat">
        <span>ضريبة القيمة المضافة (5%)</span>
        <span>0.00 د.إ</span>
      </div>
      <div class="row total">
        <span>الإجمالي</span>
        <span>0.00 د.إ</span>
      </div>
    </div>

    <!-- Place order -->
    <button class="place-order">Place order</button>
  </div>

  <script>
    document.addEventListener('DOMContentLoaded', function() {
      const items = document.querySelectorAll('.item');
      const subtotalEl = document.querySelector('.subtotal span:last-child');
      const vatEl = document.querySelector('.vat span:last-child');
      const totalEl = document.querySelector('.total span:last-child');

      function updateTotals() {
        let subtotal = 0;
        items.forEach(item => {
          const price = parseFloat(item.querySelector('.item-price').textContent);
          const quantity = parseInt(item.querySelector('input').value);
          subtotal += price * quantity;
        });
        const delivery = 10;
        const vat = subtotal * 0.05;
        const total = subtotal + delivery + vat;
        subtotalEl.textContent = subtotal.toFixed(2) + ' د.إ';
        vatEl.textContent = vat.toFixed(2) + ' د.إ';
        totalEl.textContent = total.toFixed(2) + ' د.إ';
      }

      items.forEach(item => {
        const decBtn = item.querySelector('.decrease');
        const incBtn = item.querySelector('.increase');
        const input = item.querySelector('input');

        decBtn.addEventListener('click', () => {
          if (input.value > 0) {
            input.value--;
            updateTotals();
          }
        });
        incBtn.addEventListener('click', () => {
          input.value++;
          updateTotals();
        });
        input.addEventListener('change', updateTotals);
      });

      updateTotals();
    });
  </script>
